const items = $input.all();
const alerts = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const product = row['produit'] || row['Produit'] || row['product'] || row['Product'] || row['nom'] || row['name'] || '';
  const quantityRaw = row['quantité actuelle'] || row['quantite_actuelle'] || row['Quantité'] || row['quantity'] || row['Quantity'] || row['qte'] || row['QTY'];
  const thresholdRaw = row["seuil d'alerte"] || row['seuil_alerte'] || row['seuil'] || row['alert_threshold'] || row['threshold'];

  const quantity = Number(String(quantityRaw || 0).replace(',', '.')) || 0;
  const threshold = Number(String(thresholdRaw || 0).replace(',', '.')) || 0;

  let rowIndex = null;
  if (row.__rowNumber) {
    rowIndex = Number(row.__rowNumber);
  } else {
    rowIndex = i + 2;
  }

  if (quantity <= threshold) {
    alerts.push({
      product: product,
      quantity: quantity,
      threshold: threshold,
      rowIndex: rowIndex
    });
  }
}
return [{ json: { alerts, alertsCount: alerts.length } }];

const data = $input.first().json.alerts || [];
const count = data.length;
let html = `<p>Bonjour,</p><p>Le système a détecté <strong>${count}</strong> produit(s) en dessous ou égal à leur seuil d'alerte :</p>`;
if (count > 0) {
  html += `<table border="1" cellpadding="6" cellspacing="0"><thead><tr><th>Produit</th><th>Quantité restante</th><th>Seuil d'alerte</th></tr></thead><tbody>`;
  for (const a of data) {
    html += `<tr><td>${a.product}</td><td align="center">${a.quantity}</td><td align="center">${a.threshold}</td></tr>`;
  }
  html += `</tbody></table>`;
  html += `<p>Merci de vérifier les lignes concernées dans votre feuille de stock et de réapprovisionner si nécessaire.</p>`;
}
html += `<p>Cordialement,<br/>Système d'alerte stock</p>`;

const emailItem = {
  json: {
    to: "gerant@example.com",
    subject: `Alerte rupture de stock - ${count} produit(s) en alerte`,
    html: html,
    alertsCount: count
  }
};

const updateItems = [];
const today = new Date().toISOString().split('T')[0];
for (const a of data) {
  updateItems.push({ json: { rowIndex: a.rowIndex, date: today } });
}

return [[emailItem], updateItems];
